<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Cotizaciones';$action=clean_text($_GET['action']??'list',20);$errors=[];$current=null;$statuses=['pendiente','en revisión','aceptada','rechazada','vencida'];
$clients=db()->query("SELECT u.id,u.nombre,u.email FROM usuarios u JOIN roles r ON r.id=u.role_id WHERE r.nombre='cliente' ORDER BY u.nombre")->fetchAll();$services=db()->query('SELECT id,nombre FROM servicios ORDER BY nombre')->fetchAll();
$load=function(int $id):array{$s=db()->prepare('SELECT c.*,u.nombre cliente,u.email,s.nombre servicio FROM cotizaciones c JOIN usuarios u ON u.id=c.usuario_id LEFT JOIN servicios s ON s.id=c.servicio_id WHERE c.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Cotización no encontrada.');}return$r;};if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token de cotización alterado.');$current=$load($id);}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$uid=filter_input(INPUT_POST,'usuario_id',FILTER_VALIDATE_INT);$sid=filter_input(INPUT_POST,'servicio_id',FILTER_VALIDATE_INT)?:null;$title=clean_text($_POST['titulo']??'',160);$range=clean_text($_POST['rango_presupuesto']??'',100);$details=clean_multiline($_POST['detalles']??'',4000);$amount=filter_input(INPUT_POST,'monto_propuesto',FILTER_VALIDATE_FLOAT);$proposal=clean_multiline($_POST['propuesta_admin']??'',5000);$status=clean_text($_POST['estado']??'pendiente',30);$valid=clean_text($_POST['vigencia_hasta']??'',10);if(!$uid)$errors[]='Selecciona un cliente.';if(mb_strlen($title)<4)$errors[]='Escribe un título.';if(mb_strlen($details)<10)$errors[]='Agrega detalles.';if(!in_array($status,$statuses,true))$errors[]='Estado inválido.';if(!$errors){if($fa==='create'){db()->prepare('INSERT INTO cotizaciones(usuario_id,servicio_id,titulo,rango_presupuesto,detalles,monto_propuesto,propuesta_admin,estado,vigencia_hasta) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$uid,$sid,$title,$range?:null,$details,$amount!==false?$amount:null,$proposal?:null,$status,$valid?:null]);flash('success','Cotización creada.');}else{$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('UPDATE cotizaciones SET usuario_id=?,servicio_id=?,titulo=?,rango_presupuesto=?,detalles=?,monto_propuesto=?,propuesta_admin=?,estado=?,vigencia_hasta=?,updated_at=NOW() WHERE id=?')->execute([$uid,$sid,$title,$range?:null,$details,$amount!==false?$amount:null,$proposal?:null,$status,$valid?:null,$id]);flash('success','Cotización actualizada.');}redirect('admin/cotizaciones.php');}preserve_old_input($_POST);$action=$fa==='create'?'new':'edit';}if($fa==='notify'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');$row=$load($id);$subject=clean_text($_POST['asunto']??'',180);$message=clean_multiline($_POST['mensaje']??'',4000);if(mb_strlen($subject)<3||mb_strlen($message)<5)$errors[]='Completa asunto y mensaje.';if(!$errors){db()->prepare('INSERT INTO mensajes(remitente_id,destinatario_id,cotizacion_id,asunto,mensaje) VALUES(?,?,?,?,?)')->execute([user()['id'],$row['usuario_id'],$id,$subject,$message]);flash('success','Mensaje enviado al cliente.');redirect('admin/cotizaciones.php?action=view&t='.encode_id($id));}$current=$row;$action='view';}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('DELETE FROM cotizaciones WHERE id=?')->execute([$id]);flash('success','Cotización eliminada.');redirect('admin/cotizaciones.php');}}
if($action==='list'){$items=db()->query('SELECT c.*,u.nombre cliente,s.nombre servicio FROM cotizaciones c JOIN usuarios u ON u.id=c.usuario_id LEFT JOIN servicios s ON s.id=c.servicio_id ORDER BY c.created_at DESC')->fetchAll();}
require dirname(__DIR__).'/includes/admin_header.php';
?>
<?php if(in_array($action,['new','edit'],true)):?><div class="panel-heading"><div><h1><?=$action==='new'?'Crear cotización':'Editar cotización'?></h1><p>Define una propuesta y su estado.</p></div><a class="btn btn-light" href="<?=url('admin/cotizaciones.php')?>">Cancelar</a></div><form class="form-card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$action==='new'?'create':'update'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="form-grid"><div class="field"><label>Cliente</label><select name="usuario_id" required><option value="">Selecciona</option><?php $su=(string)($_SESSION['_old']['usuario_id']??$current['usuario_id']??'');foreach($clients as$c):?><option value="<?=(int)$c['id']?>" <?=$su===(string)$c['id']?'selected':''?>><?=e($c['nombre'].' - '.$c['email'])?></option><?php endforeach;?></select></div><div class="field"><label>Servicio</label><select name="servicio_id"><option value="">Personalizado</option><?php $ss=(string)($_SESSION['_old']['servicio_id']??$current['servicio_id']??'');foreach($services as$s):?><option value="<?=(int)$s['id']?>" <?=$ss===(string)$s['id']?'selected':''?>><?=e($s['nombre'])?></option><?php endforeach;?></select></div><div class="field full"><label>Título</label><input name="titulo" value="<?=old('titulo',$current['titulo']??'')?>" required></div><div class="field"><label>Rango del cliente</label><input name="rango_presupuesto" value="<?=old('rango_presupuesto',$current['rango_presupuesto']??'')?>"></div><div class="field"><label>Monto propuesto</label><input type="number" step="0.01" min="0" name="monto_propuesto" value="<?=old('monto_propuesto',isset($current['monto_propuesto'])?(string)$current['monto_propuesto']:'')?>"></div><div class="field"><label>Estado</label><select name="estado"><?php $se=$_SESSION['_old']['estado']??$current['estado']??'pendiente';foreach($statuses as$st):?><option <?=$se===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></div><div class="field"><label>Vigencia</label><input type="date" name="vigencia_hasta" value="<?=old('vigencia_hasta',$current['vigencia_hasta']??'')?>"></div><div class="field full"><label>Detalles solicitados</label><textarea name="detalles" required><?=old('detalles',$current['detalles']??'')?></textarea></div><div class="field full"><label>Propuesta RootCode</label><textarea name="propuesta_admin"><?=old('propuesta_admin',$current['propuesta_admin']??'')?></textarea></div></div><button class="btn">Guardar</button></form>
<?php elseif($action==='view'&&$current):?><div class="panel-heading"><div><h1><?=e($current['titulo'])?></h1><p><?=e($current['cliente'].' · '.$current['email'])?></p></div><div class="actions"><a class="btn btn-light" href="<?=url('admin/cotizaciones.php')?>">Volver</a><a class="btn btn-outline" href="<?=url('admin/cotizaciones.php?action=edit&t='.encode_id((int)$current['id']))?>">Editar</a></div></div><div class="grid-2"><div class="card"><div class="detail-grid"><div class="detail-item"><strong>Servicio</strong><?=e($current['servicio']??'Personalizado')?></div><div class="detail-item"><strong>Estado</strong><span class="badge badge-<?=status_class($current['estado'])?>"><?=e($current['estado'])?></span></div><div class="detail-item"><strong>Monto</strong><?=$current['monto_propuesto']!==null?format_money($current['monto_propuesto']):'Pendiente'?></div><div class="detail-item"><strong>Vigencia</strong><?=format_date($current['vigencia_hasta'],false)?></div><div class="detail-item" style="grid-column:1/-1"><strong>Detalles</strong><?=nl2br(e($current['detalles']))?></div><div class="detail-item" style="grid-column:1/-1"><strong>Propuesta</strong><?=nl2br(e($current['propuesta_admin']??'Pendiente'))?></div></div></div><form class="card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="notify"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><h2>Notificar al cliente</h2><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="field"><label>Asunto</label><input name="asunto" value="Actualización de cotización" required></div><div class="field"><label>Mensaje</label><textarea name="mensaje" required></textarea></div><button class="btn">Enviar mensaje</button></form></div>
<?php else:?><div class="panel-heading"><div><h1>Cotizaciones</h1><p>Propuestas, montos, vigencias y comunicación.</p></div><a class="btn" href="<?=url('admin/cotizaciones.php?action=new')?>">Crear cotización</a></div><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Cliente</th><th>Título</th><th>Servicio</th><th>Monto</th><th>Estado</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="7" class="empty-state">No hay cotizaciones.</td></tr><?php endif;?><?php foreach($items as$it):?><tr><td><?=e($it['cliente'])?></td><td><?=e($it['titulo'])?></td><td><?=e($it['servicio']??'Personalizado')?></td><td><?=$it['monto_propuesto']!==null?format_money($it['monto_propuesto']):'—'?></td><td><span class="badge badge-<?=status_class($it['estado'])?>"><?=e($it['estado'])?></span></td><td><?=format_date($it['created_at'])?></td><td class="table-actions"><a class="btn btn-small btn-outline" href="<?=url('admin/cotizaciones.php?action=view&t='.encode_id((int)$it['id']))?>">Abrir</a><a class="btn btn-small btn-light" href="<?=url('admin/cotizaciones.php?action=edit&t='.encode_id((int)$it['id']))?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar esta cotización?">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<?php clear_old_input();require dirname(__DIR__).'/includes/admin_footer.php';?>
